def process(malta_dates):
    # Get first (oldest = largest BP) and last (most recent = smallest BP) dates
    first_date = malta_dates['date'].max()
    last_date = malta_dates['date'].min()
    return pd.DataFrame({'first_bp': [first_date], 'last_bp': [last_date]})

