def load() -> pd.DataFrame:
    df = pd.read_excel('data/archeology/input/climateMeasurements.xlsx', header=None, nrows=15)
    # Print each row to find the header
    rows_info = []
    for i, row in df.iterrows():
        non_null = row.dropna().tolist()
        rows_info.append({'row_index': i, 'values': str(non_null[:10])})
    return pd.DataFrame(rows_info)

def load() -> pd.DataFrame:
    import openpyxl
    wb = openpyxl.load_workbook('data/archeology/input/climateMeasurements.xlsx', read_only=True, data_only=True)
    ws = wb.active
    rows = []
    for i, row in enumerate(ws.iter_rows(values_only=True)):
        rows.append({'row_index': i, 'values': str(list(row)[:15])})
        if i >= 7:
            break
    wb.close()
    return pd.DataFrame(rows)
